import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Diving Deep with Squid | Ceph Days NYC 2024","description":"","frontmatter":{"title":"Diving Deep with Squid | Ceph Days NYC 2024","date":"2024-05-14T00:00:00.000Z","updated":"2024-05-15T00:00:00.000Z","tags":["Ceph","Squid版本","分布式存储","社区活动","蓝图存储","Rados","薄存卷","磁盘摘要","RADOS Gateway","CephFS","RBD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Diving_Deep_with_Squid_Ceph_Days_NYC_2024.md","filePath":"posts/2024/Diving_Deep_with_Squid_Ceph_Days_NYC_2024.md","lastUpdated":1780459816000}'),o={name:"posts/2024/Diving_Deep_with_Squid_Ceph_Days_NYC_2024.md"};function s(l,e,n,h,d,_){return t(),i("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>在Ceph Days NYC 2024会议上，多位Ceph项目的贡献者和技术专家汇聚一堂，讨论了Ceph分布式存储系统的最新发展。会议重点介绍了即将发布的Squid版本，回顾了2023年的重要成就，并展望了未来的发展方向。</p><h4 id="_2023年重要成就" tabindex="-1">2023年重要成就 <a class="header-anchor" href="#_2023年重要成就" aria-label="Permalink to &quot;2023年重要成就&quot;">​</a></h4><ol><li><strong>社区活动恢复</strong>：Ceph社区在疫情后成功举办了SEON会议，并计划在2023年12月在CERN举办下一次会议。</li><li><strong>存储规模增长</strong>：Ceph管理的存储量达到了一个exabyte，预计今年将达到1.5 exabytes。</li><li><strong>社区参与</strong>：社区成员广泛参与Telemetry项目，使得数据收集和分析更加全面。</li><li><strong>技术采用</strong>：Reef版本成为最受欢迎和广泛使用的版本。</li><li><strong>沟通平台</strong>：社区迁移到Slack，加强了成员间的沟通和协作。</li><li><strong>基金会更新</strong>：Ceph基金会引入了新的会员级别，并接管了部分社区管理职责。</li></ol><h4 id="squid版本亮点" tabindex="-1">Squid版本亮点 <a class="header-anchor" href="#squid版本亮点" aria-label="Permalink to &quot;Squid版本亮点&quot;">​</a></h4><ol><li><strong>性能优化</strong>：引入Elastic Shared Blob，降低快照工作负载的延迟和CPU需求；Blue Store使用RocksDB LZ4压缩，提高性能并减少空间使用。</li><li><strong>效率提升</strong>：改进CRUSH算法，允许更灵活的EC配置；增强Balancer功能，提供在线平衡能力。</li><li><strong>可用性改进</strong>：引入Manager OP Tracker，简化生产环境中Ceph管理的调试；增强Balancer功能，提供在线平衡能力。</li><li><strong>客户端优化</strong>：Crimson读取性能得到显著提升，稳定性增强；Sea Store获得多项改进，包括多核扩展优化和性能提升。</li><li><strong>Telemetry更新</strong>：增加对Crimson运行的识别，收集更多性能指标。</li><li><strong>管理工具改进</strong>：增强Ceph Dashboard，提供更直观的管理界面；改进Ceph Admin (Ceph-ADM)和Rook，简化部署和管理流程。</li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>发布计划</strong>：预计在未来几周内发布Squid版本的候选版本（RC），并邀请社区成员进行测试。</li><li><strong>社区参与</strong>：鼓励社区成员参与测试和反馈，确保版本的稳定性和质量。</li><li><strong>未来活动</strong>：计划在CERN举办SEFON会议，期待社区成员的广泛参与。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>Ceph社区在2023年取得了显著成就，Squid版本的发布将进一步提升Ceph的性能、效率和管理能力。通过持续的技术优化和社区合作，Ceph项目将继续推动分布式存储技术的前沿。</p>',11)])])}const C=a(o,[["render",s]]);export{g as __pageData,C as default};
